script:
// Egyenes ütközés – lendület- és energiamérleg
// Head-on collision – momentum and energy balance
//   m₁v₁ + m₂v₂ = m₁v₁' + m₂v₂'      e = (v₂' − v₁') / (v₁ − v₂)

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#f8f9fb");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Ütközés", en: "Collision"});
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(6);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("m1", {hu: "Tömeg m₁", en: "Mass m₁"}, 0.5, 5, 1, 0.1, "kg");
param("m2", {hu: "Tömeg m₂", en: "Mass m₂"}, 0.5, 5, 2, 0.1, "kg");
param("v1", {hu: "Kezdősebesség v₁", en: "Initial velocity v₁"}, -4, 4, 3, 0.1, "m/s");
param("v2", {hu: "Kezdősebesség v₂", en: "Initial velocity v₂"}, -4, 4, -1, 0.1, "m/s");
param("e",  {hu: "Ütközési szám e (1 = rugalmas)", en: "Restitution e (1 = elastic)"}, 0, 1, 1, 0.05, "");
// Ezek változásakor a jelenet újraindul / The scene restarts when these change
resetOn("m1", "m2", "v1", "v2", "e");
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Újraindítás", en: "Restart"}, reset);

// Fizikai világ: méterben, y felfelé; scale = px/m / Physics world: metres, y up; scale = px per metre
const W = world({gravity: 0, scale: 80, origin: [60, 230], ground: false, restitution: P.e});
// A golyó sugara a tömeg köbgyökével arányos / ball radius ∝ cube root of mass
const rad = m => 0.22 * cbrt(m);
const b1 = ball({x: 3, y: 0, vx: P.v1, m: P.m1, r: rad(P.m1), color: C.blue, label: "1"});
const b2 = ball({x: 7.5, y: 0, vx: P.v2, m: P.m2, r: rad(P.m2), color: C.orange, label: "2"});

// Vízszintes oszlop egy értékhez / horizontal bar for one value
function bar(label, value, y, color, sc) {
  const x0 = 520, w = clamp(value * sc, -400, 400);
  rect(min(x0, x0 + w), y, abs(w), 18, {fill: color});
  text(label, 170, y + 14, {size: 14});
  text(fmt(value, 2), 960, y + 14, {size: 13, align: "right", font: "IBM Plex Mono, monospace"});
}

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const y0 = wy(0);
  line(20, y0, 980, y0, {stroke: "#c9d0da", lw: 2, dash: [8, 8]});
  line(wx(0), y0 + 70, wx(11), y0 + 70, {stroke: C.gray, lw: 1});
  for (let x = 0; x <= 11; x++) {
    line(wx(x), y0 + 70, wx(x), y0 + 78, {stroke: C.gray, lw: 1});
    text(x + " m", wx(x), y0 + 94, {size: 11, color: C.gray, align: "center"});
  }
  // A fizikai világ (golyók, talaj) kirajzolása / Draw the physics world (balls, ground)
  drawWorld();
  for (const [bb, lab] of [[b1, "v₁"], [b2, "v₂"]]) {
    if (abs(bb.vx) > 0.02) vector(wx(bb.x), y0 - ws(bb.r) - 20, bb.vx * 40, 0, {stroke: bb.color, lw: 3}, lab);
  }

  const p1 = P.m1 * b1.vx, p2 = P.m2 * b2.vx;
  const E1 = 0.5 * P.m1 * b1.vx ** 2, E2 = 0.5 * P.m2 * b2.vx ** 2;
  line(520, 380, 520, 590, {stroke: C.gray, lw: 1});
  text({hu: "Lendület p [kg·m/s]", en: "Momentum p [kg·m/s]"}, 170, 392, {size: 13, color: C.gray, bold: true});
  bar("p₁", p1, 402, C.blue, 18);
  bar("p₂", p2, 426, C.orange, 18);
  bar("Σp", p1 + p2, 450, C.ink, 18);
  text({hu: "Mozgási energia E [J]", en: "Kinetic energy E [J]"}, 170, 500, {size: 13, color: C.gray, bold: true});
  bar("E₁", E1, 510, C.blue, 8);
  bar("E₂", E2, 534, C.orange, 8);
  bar("ΣE", E1 + E2, 558, C.ink, 8);

  const M = P.m1 + P.m2, pt = P.m1 * P.v1 + P.m2 * P.v2;
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Teljes lendület Σp", en: "Total momentum Σp"}, p1 + p2, "kg·m/s");
  show({hu: "Teljes mozgási energia ΣE", en: "Total kinetic energy ΣE"}, E1 + E2, "J");
  show({hu: "v₁ most", en: "v₁ now"}, b1.vx, "m/s");
  show({hu: "v₂ most", en: "v₂ now"}, b2.vx, "m/s");
  if (P.v1 > P.v2) {
    show({hu: "v₁' (elmélet)", en: "v₁' (theory)"}, (pt - P.m2 * P.e * (P.v1 - P.v2)) / M, "m/s");
    show({hu: "v₂' (elmélet)", en: "v₂' (theory)"}, (pt + P.m1 * P.e * (P.v1 - P.v2)) / M, "m/s");
  } else {
    show({hu: "Ütközés", en: "Collision"}, tr({hu: "nem lesz (v₁ ≤ v₂)", en: "none (v₁ ≤ v₂)"}), "");
  }

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot("v₁", b1.vx, {unit: "m/s", color: C.blue});
  plot("v₂", b2.vx, {unit: "m/s", color: C.orange});
  plot("ΣE", E1 + E2, {unit: "J", color: C.ink, min: 0});
});
